
'use strict';
const D=JSON.parse(document.getElementById('report-data').textContent), E=D.editorial;
const $=id=>document.getElementById(id);
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=new Intl.NumberFormat('ko-KR'),num=n=>nf.format(n),pct=n=>Number(n).toFixed(2),monthName=m=>Number(m.slice(5))+'월';
const safeURL=url=>{try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';}};
const sourceLink=(id,short=false)=>{const s=E.sources[id];return `<a href="${escapeHTML(safeURL(s.url))}" target="_blank" rel="noopener noreferrer">${escapeHTML(short?s.name.split(' · ')[0]:s.name)} ↗</a>`;};
const refButton=(ids,label='대표 기사 보기 ↗')=>`<button class="ref-button" data-articles="${escapeHTML(ids.join(','))}">${escapeHTML(label)}</button>`;
const trendDefs=[{id:'T003',label:'AI 인프라',color:'#087b83'},{id:'T019',label:'대미 투자·통상',color:'#7560a3'},{id:'T055',label:'주택 공급',color:'#b67427'},{id:'T002',label:'AI 안전·거버넌스',color:'#bd5b66'}];
const state={weekScope:'economy',todayLimit:8,scope:'economy',mode:'count',scale:'global',sectorFilter:'all',trend:new Set(trendDefs.map(t=>t.id)),dialogIds:[],dialogSector:null,limit:20};
function getRanking(scope){return D.ranking.filter(x=>scope==='all'||x.economic).sort((a,b)=>b.count-a.count||a.id.localeCompare(b.id)).slice(0,10);}
function renderDailyMeta(){
 $('publication-info').textContent=`발행일 ${D.reportDate} · 자료 기준일 ${D.cutoff} · 마지막 기사일 ${D.lastArticleDate||'확인 불가'}`;
 $('coverage-tag').textContent=`${D.sourceStart}–${D.cutoff} · 진행월 별도 표시`;
 for(const [id,n] of [['metric-total',D.uniqueTotal],['metric-today',D.today.total],['metric-week',D.weekly.total],['metric-month',D.currentTotal]])$(id).innerHTML=num(n)+'<small>건</small>';
 $('metric-range').textContent=`${D.sourceStart}–${D.cutoff} · Article_ID 중복 제거`;
 $('metric-today-desc').textContent=D.reportDate+` · 매일경제 ${D.today.publishers['매일경제']||0} / 한국경제 ${D.today.publishers['한국경제']||0}`;
 $('metric-week-desc').textContent=`${D.weekly.start}–${D.weekly.end}`;
 $('metric-month-desc').textContent=`${D.currentStart}–${D.currentEnd}`;
 $('recent-date').innerHTML=`현재 ${D.currentStart}–${D.currentEnd}<br>이전 ${D.previousStart}–${D.previousEnd}`;
 $('classification-note').textContent=`테마 미분류는 이전 ${num(D.previousUnmapped)}건(${pct(D.previousUnmapped/(D.previousTotal||1)*100)}%), 현재 ${num(D.currentUnmapped)}건(${pct(D.currentUnmapped/(D.currentTotal||1)*100)}%)이며 모두 비중의 분모에 포함합니다. 분류율·재분류 차이가 있어 비중 이동을 순수한 관심 변화로 단정하지 않습니다. 막대를 누르면 해당 기사를 확인할 수 있습니다.`;
 $('narrative-period').textContent=`최근 완료된 ${D.narrativeMonths.map(monthName).join('·')}의 기사 분포와 대표 기사를 함께 읽습니다.`;
 $('narrative-date').textContent=D.narrativeMonths.join(' / ');
 $('trend-coverage').textContent=D.narrativeMonths.map(m=>`${monthName(m)} ${num(D.coverage[m].total)}건`).join(' · ');
 const ai=D.ranking.find(x=>x.id==='T003');$('trend-interpretation').innerHTML='<strong>월별 추세와 최신 30일은 서로 다른 창입니다.</strong> '+(ai?`AI 인프라 테마는 최신 30일 ${ai.count}건(${pct(ai.share)}%), 이전 30일 ${ai.previous}건(${pct(ai.previousShare)}%)입니다. `:'')+'기사 관심의 변화를 투자 규모의 변화로 단정하지 않습니다.';
 $('partial-month-note').innerHTML=`<strong>${monthName(D.cutoff.slice(0,7))} 1~${Number(D.cutoff.slice(8))}일은 진행 중인 달입니다.</strong> 회색 사선으로 표시하며 색상 비교와 분야별 최대월 계산에서 제외합니다. 수집되지 않은 날짜의 사유는 확인 전까지 미확인입니다.`;
 $('editorial-status').textContent=E.targetedReview?`기사 집계 기준 ${D.cutoff}. 추가 검토 ${E.targetedReview.date}: ${E.targetedReview.scope}. 7~9월 서사와 그 외 기존 해석·관찰 변수는 ${E.analysisCheckedAt} 검토 내용을 유지했습니다. 출처마다 실제 확인일을 표시하며 전체 내용을 매일 재검증한 것으로 표시하지 않습니다.`:`기사 집계 기준 ${D.cutoff}. 구조적 해석·관찰 변수·공식 출처는 마지막 검토일 ${E.analysisCheckedAt}의 내용을 유지했습니다. 아래 출처의 확인일을 함께 보세요. 새로운 계약·정책·수치를 매일 재검증한 것으로 표시하지 않습니다.`;
 $('generation-info').textContent=`자료 생성 ${D.generatedAt} · 보고서 발행 ${D.reportDate} · 검색 사전 ${D.dictionaryVersion}`;
}
function renderToday(){
 const publisher=$('today-publisher').value,query=$('today-query').value.trim().toLowerCase();
 const rows=D.today.articleIds.map(id=>D.articles[id]).filter(a=>(publisher==='all'||a.publisher===publisher)&&a.headline.toLowerCase().includes(query));
 $('today-date').textContent=D.today.date+' · '+num(D.today.total)+'건';
 $('today-status').innerHTML=D.today.total?`<strong>${D.reportDate} 기사 ${num(D.today.total)}건이 확인됐습니다.</strong> 매일경제 ${D.today.publishers['매일경제']||0}건 · 한국경제 ${D.today.publishers['한국경제']||0}건. 제목을 누르면 개별 기사로 이동합니다.`:`<strong>${D.reportDate}의 기사는 현재 자료에서 확인되지 않습니다.</strong> 마지막 기사일은 ${D.lastArticleDate||'확인 불가'}입니다. 당일 수집 완료·휴간 여부는 미확인입니다.`;
 $('today-topics').innerHTML=D.today.ranking.filter(r=>r.economic).slice(0,4).map(r=>`<button class="topic-pill" data-articles="${escapeHTML(r.articleIds.join(','))}">${escapeHTML(r.name)} · ${r.count}건</button>`).join('');
 $('today-count').textContent=`${num(rows.length)}건 · ${num(Math.min(state.todayLimit,rows.length))}건 표시`;
 $('today-articles').innerHTML=rows.length?rows.slice(0,state.todayLimit).map(a=>`<article class="daily-card"><div class="daily-meta"><span>${escapeHTML(a.date)}</span><span>${escapeHTML(a.publisher)} · ${escapeHTML(a.section)}</span></div><h3><a href="${escapeHTML(safeURL(a.url))}" target="_blank" rel="noopener noreferrer">${escapeHTML(a.headline)} ↗</a></h3><p>${escapeHTML(a.summary||'짧은 요약이 없습니다.')}</p><span class="daily-theme">${escapeHTML(a.theme_id?D.themes[a.theme_id]:'테마 미분류'+(a.candidate?' · '+a.candidate:''))}</span></article>`).join(''):'<p class="empty">조건에 맞는 당일 기사가 없습니다.</p>';
 $('today-more').classList.toggle('hidden',state.todayLimit>=rows.length);
}
function renderWeekly(){
 const w=D.weekly,rows=w.ranking.filter(r=>state.weekScope==='all'||r.economic).slice(0,10),max=Math.max(1,...rows.flatMap(r=>[r.share,r.previousShare]));
 $('weekly-date').innerHTML=`최근 ${w.start}–${w.end}<br>직전 ${w.previousStart}–${w.previousEnd}`;
 $('week-ranking').innerHTML=rows.length?rows.map((r,i)=>`<button class="rank-row" data-week-theme="${escapeHTML(r.id)}" aria-label="${escapeHTML(r.name)} ${r.count}건 기사 보기"><span class="rank-index">${String(i+1).padStart(2,'0')}</span><span class="rank-name">${escapeHTML(r.name)}<div class="bar-track" aria-hidden="true"><span class="bar-prev" style="width:${r.previousShare/max*100}%"></span><span class="bar-now" style="width:${r.share/max*100}%"></span></div></span><span class="rank-value">${r.count}건<small>${pct(r.share)}% · <span class="delta ${r.deltaPP>=0?'up':'down'}">${r.deltaPP>=0?'+':''}${pct(r.deltaPP)}%p</span></small></span></button>`).join(''):'<p class="empty">집계된 테마가 없습니다.</p>';
 const economy=w.ranking.filter(r=>r.economic),leader=economy[0],rise=[...economy].sort((a,b)=>b.deltaPP-a.deltaPP)[0];
 const observations=[];
 if(leader)observations.push({title:'가장 자주 언급된 경제·산업 주제',text:`${leader.name} ${leader.count}건. 직전 7일 ${leader.previous}건에서 기사 비중은 ${leader.deltaPP>=0?'+':''}${pct(leader.deltaPP)}%p 변했습니다.`});
 if(rise&&rise.deltaPP>0)observations.push({title:'기사 비중이 가장 많이 늘어난 주제',text:`${rise.name}: ${pct(rise.previousShare)}% → ${pct(rise.share)}%. 테마 분류 변경과 새 기사 내용도 함께 확인해야 합니다.`});
 const digital=w.ranking.find(r=>r.id==='T103');if(digital)observations.push({title:'새 정식 테마로 잡힌 스테이블코인',text:`${digital.name} ${digital.count}건입니다. 승인된 테마 승격과 과거 기사 재매핑이 반영돼 이전 발행판과 분류 기준이 달라질 수 있습니다.`});
 $('week-observations').innerHTML=observations.map(o=>`<div class="week-change"><strong>${escapeHTML(o.title)}</strong><p>${escapeHTML(o.text)}</p></div>`).join('');
 $('week-coverage').textContent=`최근 7일 전체 ${num(w.total)}건 / 직전 7일 ${num(w.previousTotal)}건. 미분류 ${num(w.unmapped)}건(${pct(w.unmapped/(w.total||1)*100)}%) / ${num(w.previousUnmapped)}건(${pct(w.previousUnmapped/(w.previousTotal||1)*100)}%). 비중의 분모는 미분류를 포함한 전체 기사입니다.`;
}
function getSectors(filter){const energy=['power','oilgas','ess','solar','nuclear','smr'],growth=['semiconductor','ai','memory','robot','bio'];return D.industry.filter(s=>filter==='all'||(filter==='energy'?energy:growth).includes(s.id));}
function heatValue(cell,mode){return mode==='count'?cell.count:cell.share;}
function formatHeat(cell,mode){return mode==='count'?String(cell.count):Number(cell.share).toFixed(1)+'%';}
function heatColor(v,max,scale,mode){const colors=['#f1f5f5','#e5f1ef','#cee5e0','#a9d2ca','#78b5aa','#368f86','#0d625f'];if(scale==='row'){return colors[v===0?0:Math.max(1,Math.ceil(v/(max||1)*6))];}const cuts=mode==='count'?[0,1,10,30,60,120,240]:[0,.01,1,2,4,8,16];let index=0;cuts.forEach((t,i)=>{if(v>=t)index=i;});return colors[index];}
function makeCSV(){const header=['industry','month','matched_articles','total_articles','share_percent','complete_month','dictionary_version'],lines=[header];D.industry.forEach(s=>D.months.forEach(m=>{const c=s.cells[m];lines.push([s.name,m,c.count,c.total,c.share,D.completedMonths.includes(m),D.dictionaryVersion]);}));const q=v=>'"'+String(v).replace(/"/g,'""')+'"';return '\uFEFF'+lines.map(row=>row.map(q).join(',')).join('\r\n');}
function renderRanking(){const rows=getRanking(state.scope),max=Math.max(1,...rows.flatMap(r=>[r.share,r.previousShare]));$('ranking').innerHTML=rows.map(r=>{const delta=(r.deltaPP>=0?'+':'')+pct(r.deltaPP)+'%p',n=1+rows.filter(x=>x.count>r.count).length;return `<button class="rank-row" data-theme="${r.id}" aria-label="${escapeHTML(r.name)} ${r.count}건. 기사 목록 보기"><span class="rank-index">${String(n).padStart(2,'0')}</span><span class="rank-name">${escapeHTML(r.name)}<div class="bar-track" aria-hidden="true"><span class="bar-prev" style="width:${r.previousShare/max*100}%"></span><span class="bar-now" style="width:${r.share/max*100}%"></span></div></span><span class="rank-value">${r.count}건<small>${pct(r.share)}% · <span class="delta ${r.deltaPP>=0?'up':'down'}">${delta}</span></small></span></button>`;}).join('');const top=rows[0];$('rank-notice').innerHTML=top?`<strong>${state.scope==='economy'?'경제·산업':'전체 시사'} 범위입니다.</strong> 현재 1위는 ${escapeHTML(top.name)} ${top.count}건(${pct(top.share)}%)입니다. 테마 미분류도 비중의 분모에 포함합니다.`:'집계된 테마가 없습니다.';}
function renderEditorial(){ $('hero-summary').textContent=E.summary;
 $('reading-cards').innerHTML=E.recentNotes.map(x=>`<article class="reading-card"><h3>${escapeHTML(x.title)}</h3><p>${escapeHTML(x.text)}</p>${refButton(x.articles)}</article>`).join('');
 const sm=D.industry.find(s=>s.id==='smr');const smrIds=Object.entries(D.articles).filter(([id,a])=>a.date>=D.currentStart&&a.date<=D.currentEnd&&a.matches.smr).map(([id])=>id);
 const signals=D.searchSignals.concat([{id:'smr',label:'SMR',current:{count:smrIds.length,unmapped:smrIds.filter(id=>!D.articles[id].theme_id).length,articleIds:smrIds}}]);
 $('search-signals').innerHTML=signals.map(s=>`<article class="signal-card"><div class="signal-name">${escapeHTML(s.label)}</div><div class="signal-number">${s.current.count}<small>건</small></div><p>테마 미분류 ${s.current.unmapped}건 포함</p>${refButton(s.current.articleIds,'일치 기사 확인 ↗')}</article>`).join('');
 $('timeline').innerHTML=E.narrative.map(x=>`<article class="month-card"><div class="month-num">${monthName(x.month)} / ${num(D.coverage[x.month].total)}건</div><div class="eyebrow">${escapeHTML(x.eyebrow)}</div><h3>${escapeHTML(x.title)}</h3><p>${escapeHTML(x.text)}</p><div class="month-stat">${x.themes.map(t=>{const c=D.themeSeries[t][x.month];return `<div><span>${escapeHTML(D.themes[t])}</span><strong>${c.count}건 · ${pct(c.share)}%</strong></div>`;}).join('')}</div><p class="month-question">${escapeHTML(x.question)}</p>${refButton(x.articles)}</article>`).join('');
 $('prehistory').innerHTML=E.prehistory.map(x=>{const c=D.themeSeries[x.theme][x.month];return `<article class="prehistory-card"><span class="eyebrow">${monthName(x.month)} · ${num(D.coverage[x.month].total)}건</span><h4>${escapeHTML(x.title)}</h4><p>${escapeHTML(x.text)}</p><div class="pre-stat">${escapeHTML(D.themes[x.theme])} ${c.count}건 · ${pct(c.share)}%</div>${refButton(x.articles)}</article>`;}).join('');
 $('structural').innerHTML=E.structural.map(x=>`<div><strong>${escapeHTML(x.title)}</strong><p>${escapeHTML(x.text)}</p></div>`).join('');
 $('crosschecks').innerHTML=E.primaryCrosschecks.map(x=>`<article class="crosscheck"><span class="stage">${escapeHTML(x.stage)}</span><h4>${escapeHTML(x.title)}</h4><p>${escapeHTML(x.text)}</p>${sourceLink(x.source)}</article>`).join('');
}
function renderTrend(){ const months=D.narrativeMonths,selected=trendDefs.filter(t=>state.trend.has(t.id));
 $('trend-legend').innerHTML=trendDefs.map(t=>`<button data-trend="${t.id}" aria-pressed="${state.trend.has(t.id)}"><i style="background:${t.color}"></i>${escapeHTML(t.label)}</button>`).join('');
 const w=1000,h=310,left=55,right=50,top=28,bottom=42,max=Math.max(2,Math.ceil(Math.max(...trendDefs.flatMap(t=>months.map(m=>D.themeSeries[t.id]?.[m]?.share||0)))/2)*2),x=i=>left+i*(w-left-right)/Math.max(1,months.length-1),y=v=>h-bottom-v/max*(h-top-bottom);
 let svg=`<svg class="trend-svg" viewBox="0 0 ${w} ${h}" role="img" aria-labelledby="trend-title trend-desc"><title id="trend-title">최근 완료된 3개월 경제 테마 비중 변화</title><desc id="trend-desc">${months.map(monthName).join(', ')}의 AI 인프라, 대미 투자·통상, 주택 공급, AI 안전·거버넌스 기사 비중. 정확한 값과 기사 목록은 아래 표에서 확인할 수 있습니다.</desc>`;
 for(let v=0;v<=max;v+=2)svg+=`<line class="grid" x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}"/><text x="${left-13}" y="${y(v)+4}" text-anchor="end" fill="#71838c" font-size="11">${v}%</text>`;
 months.forEach((m,i)=>{svg+=`<text x="${x(i)}" y="${h-14}" text-anchor="middle" fill="#526770" font-size="12">${monthName(m)}</text>`;});
 selected.forEach(t=>{const values=months.map(m=>D.themeSeries[t.id][m].share);svg+=`<polyline fill="none" stroke="${t.color}" stroke-width="3" stroke-linejoin="round" points="${values.map((v,i)=>x(i)+','+y(v)).join(' ')}"/>`;values.forEach((v,i)=>{const offset=t.id==='T055'?16:-12;svg+=`<g><circle cx="${x(i)}" cy="${y(v)}" r="5" fill="${t.color}" stroke="white" stroke-width="2"/><text x="${x(i)}" y="${y(v)+offset}" text-anchor="middle" fill="${t.color}" font-weight="750" font-size="11">${pct(v)}%</text><title>${escapeHTML(t.label)} · ${monthName(months[i])}: ${D.themeSeries[t.id][months[i]].count}건 / ${D.coverage[months[i]].total}건</title></g>`;});});
 $('trend-chart').innerHTML=svg+'</svg>';
 $('trend-table').innerHTML='<table class="data-table"><thead><tr><th>테마</th>'+months.map(m=>`<th>${monthName(m)} · 건수 (비중)</th>`).join('')+'</tr></thead><tbody>'+trendDefs.map(t=>`<tr><th style="color:${t.color}">${escapeHTML(t.label)}</th>`+months.map(m=>{const c=D.themeSeries[t.id][m];return `<td><button data-series="${t.id}|${m}" aria-label="${escapeHTML(t.label)} ${monthName(m)} ${c.count}건 기사 보기">${c.count} (${pct(c.share)}%)</button></td>`;}).join('')+'</tr>').join('')+'</tbody></table>';
}
function renderWatch(){ $('watch-grid').innerHTML=E.watch.map((x,i)=>`<article class="watch-card"><div class="watch-header"><span class="watch-num">${String(i+1).padStart(2,'0')}</span><div><h3>${escapeHTML(x.title)}</h3><span class="watch-period">${escapeHTML(x.period)}</span></div></div><p class="why">${escapeHTML(x.why)}</p><div class="measure">${escapeHTML(x.measure)}</div><div class="direction"><b>확인되면 해석 강화</b>${escapeHTML(x.up)}</div><div class="direction down"><b>확인되면 보류·하향 검토</b>${escapeHTML(x.down)}</div><div class="watch-links">${x.sources.map(s=>sourceLink(s,true)).join('')}</div>${x.articles?refButton(x.articles,'관련 기사 보기 ↗'):''}</article>`).join('');
 $('calendar').innerHTML=Array.from({length:3},(_,i)=>{const d=new Date(D.cutoff+'T00:00:00Z');d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+i);return d.toISOString().slice(0,7)}).map(m=>`<div><div class="calendar-month">${monthName(m)}</div>`+E.calendar.filter(e=>e.date.startsWith(m)&&(e.end||e.date)>=D.reportDate).map(e=>{const d=Number(e.date.slice(8)),end=e.end?'–'+Number(e.end.slice(8)):'';return `<div class="calendar-event"><span class="event-date">${d}${end}일</span><a href="${escapeHTML(E.sources[e.source].url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(e.label)} ↗</a></div>`;}).join('')+'</div>').join('');}
function renderHeat(){ const sectors=getSectors(state.sectorFilter),months=D.months;
 $('heat-table').innerHTML='<thead><tr><th scope="col">산업·세부 분야</th>'+months.map(m=>`<th scope="col" class="${D.completedMonths.includes(m)?'':'partial-head'}">${monthName(m)}${D.completedMonths.includes(m)?'':' 1~'+Number(D.cutoff.slice(8))+'일'}<small>N=${num(D.coverage[m].total)}${D.completedMonths.includes(m)?'':' · 진행월'}</small></th>`).join('')+'</tr></thead><tbody>'+sectors.map(s=>{const max=Math.max(...D.completedMonths.map(m=>heatValue(s.cells[m],state.mode)));return `<tr><th scope="row">${escapeHTML(s.name)}${['memory','smr','ess'].includes(s.id)?'<small>중복 가능</small>':''}</th>`+months.map(m=>{const c=s.cells[m],v=heatValue(c,state.mode),color=heatColor(v,max,state.scale,state.mode),fg=color==='#0d625f'||color==='#368f86'?'#fff':'#1b4d4b',partial=!D.completedMonths.includes(m),label=`${s.name} ${monthName(m)} ${partial?'1~'+Number(D.cutoff.slice(8))+'일 ':''}${c.count}건, 전체 ${c.total}건의 ${pct(c.share)}%. 기사 보기`;return `<td><button type="button" class="heat-cell ${partial?'partial':''}" data-sector="${s.id}|${m}" title="${escapeHTML(label)}" aria-label="${escapeHTML(label)}" style="background:${color};color:${fg}">${formatHeat(c,state.mode)}</button></td>`;}).join('')+'</tr>';}).join('')+'</tbody>';
 const palettes=['#f1f5f5','#e5f1ef','#cee5e0','#a9d2ca','#78b5aa','#368f86','#0d625f'],labels=state.scale==='row'?['0','낮음','','','','','분야 내 최대']:state.mode==='count'?['0','1–9','10–29','30–59','60–119','120–239','240+']:['0','0–1%','1–2%','2–4%','4–8%','8–16%','16%+'];
 $('heat-legend').innerHTML='<span>색상 구간</span>'+palettes.map((c,i)=>`<span class="step"><i class="legend-box" style="background:${c}"></i>${labels[i]}</span>`).join('');
 $('heat-note').textContent=(state.mode==='count'?'숫자: 분야 내 중복 제거한 검색 일치 기사 수. ':'숫자: 해당 월 전체 기사 대비 검색 일치 비중(소수 첫째 자리 표시). ')+(state.scale==='global'?'색상: 모든 분야에 같은 구간을 적용합니다. ':'색상: 각 분야의 완료된 월 최대값을 기준으로 정규화합니다. 분야 간 색의 진하기를 직접 비교하지 않습니다. ');
}
function renderMethod(){const months=D.months;$('coverage-table').innerHTML='<table class="data-table"><thead><tr><th>월</th><th>전체 기사</th><th>매일경제 · 수집일</th><th>한국경제 · 수집일</th><th>미분류 · 비중</th></tr></thead><tbody>'+months.map(m=>{const c=D.coverage[m];return `<tr><th>${monthName(m)}${D.completedMonths.includes(m)?'':' 1~'+Number(D.cutoff.slice(8))+'일'}</th><td>${num(c.total)}</td><td>${num(c.publishers['매일경제'])}건 · ${c.days['매일경제']}일</td><td>${num(c.publishers['한국경제'])}건 · ${c.days['한국경제']}일</td><td>${num(c.unmapped)}건 · ${pct(c.unmapped/c.total*100)}%</td></tr>`;}).join('')+'</tbody></table>';
 $('dictionary-table').innerHTML=D.industry.map(s=>`<tr><th>${escapeHTML(s.name)}</th><td><code>${escapeHTML(s.pattern)}</code></td></tr>`).join('');$('economy-filter-list').textContent=D.economicThemeIds.join(', ');
 $('data-cautions').innerHTML='<h4>원본 날짜와 요약 시점이 어긋나는 사례 · 검증 대기</h4>'+E.dataCautions.map(x=>`<p>${escapeHTML(x.issue)}<br>${refButton([x.article],'해당 기사 확인 ↗')}</p>`).join('');
 $('source-list').innerHTML=Object.values(E.sources).map(s=>`<a class="source-link" href="${escapeHTML(safeURL(s.url))}" target="_blank" rel="noopener noreferrer"><strong>${escapeHTML(s.name)} ↗</strong><span>${escapeHTML(s.type)} · 확인 ${s.checked}</span></a>`).join('');}
function openArticles(ids,title,description='',sector=null){state.dialogIds=[...new Set(ids)].filter(id=>D.articles[id]);state.dialogSector=sector;state.limit=20;$('dialog-title').textContent=title;$('dialog-description').textContent=description||'기사 날짜·신문·테마와 원문 링크를 확인하세요. 기사 링크는 집계 자료에 저장된 네이버 지면 주소를 그대로 사용합니다.';$('article-query').value='';$('publisher-filter').value='all';renderArticles();$('article-dialog').showModal();}
function filteredArticles(){const query=$('article-query').value.trim().toLocaleLowerCase(),publisher=$('publisher-filter').value;return state.dialogIds.map(id=>D.articles[id]).filter(a=>(publisher==='all'||a.publisher===publisher)&&a.headline.toLocaleLowerCase().includes(query)).sort((a,b)=>b.date.localeCompare(a.date)||a.article_id.localeCompare(b.article_id));}
function renderArticles(){const rows=filteredArticles();$('article-count').textContent=`${num(rows.length)}건 · ${num(Math.min(state.limit,rows.length))}건 표시`;$('article-list').innerHTML=rows.length?rows.slice(0,state.limit).map(a=>{const hit=state.dialogSector?a.matches[state.dialogSector]:null;return `<article class="article-item"><div class="article-meta"><span>${a.date}</span><span>${escapeHTML(a.publisher)} ${escapeHTML(a.section)}</span><span>${a.theme_id?escapeHTML(D.themes[a.theme_id]||a.theme_id):'테마 미분류'}</span></div><a href="${escapeHTML(safeURL(a.url))}" target="_blank" rel="noopener noreferrer">${escapeHTML(a.headline)} ↗</a>${hit?`<span class="article-match">${hit.field} 일치: …${escapeHTML(hit.text)}…</span>`:''}<div class="article-id">${escapeHTML(a.article_id)}</div></article>`;}).join(''):'<p class="empty">선택한 조건에 일치하는 기사가 없습니다.</p>';$('article-more').classList.toggle('hidden',rows.length<=state.limit);}
function download(text,filename,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.weekScope){state.weekScope=b.dataset.weekScope;document.querySelectorAll('#week-scope button').forEach(x=>x.setAttribute('aria-pressed',x===b));renderWeekly();}
 if(b.dataset.weekTheme){const r=D.weekly.ranking.find(x=>x.id===b.dataset.weekTheme);openArticles(r.articleIds,r.name,`${D.weekly.start}–${D.weekly.end} · ${r.count}건 / 전체 ${D.weekly.total}건 (${pct(r.share)}%)`);}
 if(b.dataset.scope){state.scope=b.dataset.scope;document.querySelectorAll('#rank-scope button').forEach(x=>x.setAttribute('aria-pressed',x===b));renderRanking();}
 if(b.dataset.mode){state.mode=b.dataset.mode;document.querySelectorAll('#heat-mode button').forEach(x=>x.setAttribute('aria-pressed',x===b));renderHeat();}
 if(b.dataset.theme){const r=D.ranking.find(x=>x.id===b.dataset.theme);openArticles(r.articleIds,r.name,`${D.currentStart}–${D.currentEnd} · ${r.count}건 / 전체 ${D.currentTotal}건 (${pct(r.share)}%)`);}
 if(b.dataset.articles)openArticles(b.dataset.articles.split(','),b.dataset.title||'대표·관련 기사');
 if(b.dataset.trend){const t=b.dataset.trend;state.trend.has(t)?state.trend.delete(t):state.trend.add(t);renderTrend();}
 if(b.dataset.series){const [t,m]=b.dataset.series.split('|'),c=D.themeSeries[t][m];openArticles(c.articleIds,D.themes[t],`${monthName(m)} · ${c.count}건 / 전체 ${c.total||D.coverage[m].total}건 (${pct(c.share)}%)`);}
 if(b.dataset.sector){const [id,m]=b.dataset.sector.split('|'),s=D.industry.find(x=>x.id===id),c=s.cells[m];openArticles(c.articleIds,`${s.name} · ${monthName(m)}${D.completedMonths.includes(m)?'':' 1~'+Number(D.cutoff.slice(8))+'일'}`,`${c.count}건 / 전체 ${c.total}건 (${pct(c.share)}%) · 제목+독립 요약의 원시 검색 일치. 분야별 Article_ID 1회 집계.`,id);}
});
$('heat-filter').addEventListener('change',e=>{state.sectorFilter=e.target.value;renderHeat();});$('heat-scale').addEventListener('change',e=>{state.scale=e.target.value;renderHeat();});
$('dialog-close').addEventListener('click',()=>$('article-dialog').close());$('article-dialog').addEventListener('click',e=>{if(e.target===$('article-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('article-query').addEventListener('input',()=>{state.limit=20;renderArticles();});$('publisher-filter').addEventListener('change',()=>{state.limit=20;renderArticles();});$('article-more').addEventListener('click',()=>{state.limit+=20;renderArticles();});
$('today-query').addEventListener('input',()=>{state.todayLimit=8;renderToday();});$('today-publisher').addEventListener('change',()=>{state.todayLimit=8;renderToday();});$('today-more').addEventListener('click',()=>{state.todayLimit+=8;renderToday();});
$('download-csv').addEventListener('click',()=>download(makeCSV(),'economic-industry-'+D.sourceStart+'-to-'+D.cutoff+'.csv','text/csv;charset=utf-8'));
$('download-metrics').addEventListener('click',()=>{const out={...D};delete out.articles;delete out.editorial;out.articleLinks=Object.fromEntries(Object.entries(D.articles).map(([id,article])=>[id,article.url]));download(JSON.stringify(out,null,2),'economic-narrative-metrics-'+D.reportDate+'.json','application/json');});
$('energy-evidence').addEventListener('click',()=>openArticles(['ART-009-0005739147','ART-009-0005741562','ART-009-0005741585'],'발전·전력망·저장을 연결하는 기사','마지막 기사는 날짜와 요약의 연도가 어긋나 제도 시행연도 검증을 보류했습니다.'));
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('.nav a').forEach(a=>{a.removeAttribute('aria-current');if(a.getAttribute('href')==='#'+e.target.id)a.setAttribute('aria-current','location');});}});},{rootMargin:'-15% 0px -60% 0px'});document.querySelectorAll('section.section').forEach(s=>observer.observe(s));}
renderDailyMeta();renderToday();renderWeekly();renderEditorial();renderRanking();renderTrend();renderWatch();renderHeat();renderMethod();
window.EconomyReport={getRanking,getSectors,heatValue,heatColor,formatHeat,makeCSV,filteredArticles,openArticles,data:D,state};
